import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def phi(n):
    """Computes Euler's totient function phi(n)."""
    if n == 0:
        return 0
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def get_order(a, n):
    """Computes the multiplicative order of a modulo n."""
    if gcd(a, n) != 1:
        # Order is undefined, but since we ensure gcd(3, n) = 1 in the main loop,
        # this should not happen for our purpose.
        return 0 

    phi_n = phi(n)

    # Check divisors of phi_n
    for k in range(1, phi_n + 1):
        if phi_n % k == 0:
            if pow(a, k, n) == 1:
                return k
    return phi_n # Should theoretically be found before this point

def C(d):
    """Calculates the number of cycles C(d) for x -> 3x mod d on (Z/dZ)*."""
    if gcd(3, d) != 1:
        # If gcd(3, d) != 1, C(d) is not well-defined based on the derived formula.
        # Given the context (summing over divisors of m where 3 not | m), this case 
        # should not be reached for the divisors d' we sum over.
        return 0 

    phi_d = phi(d)
    order_3 = get_order(3, d)

    # C(d) = phi(d) / ord_d(3)
    return phi_d // order_3

def calculate_Nc_and_find_odd(M_max=100):
    """Calculates N_C(m) and finds m where N_C(m) is odd."""

    odd_m_list = []

    # Iterate over m in the range 4 <= m <= 100 such that 3 does not divide m.
    for m in range(4, M_max + 1):
        if m % 3 == 0:
            continue

        # Find all divisors d' of m such that d' > 1
        divisors = []
        for d_prime in range(2, int(math.sqrt(m)) + 1):
            if m % d_prime == 0:
                divisors.append(d_prime)
                if d_prime * d_prime != m:
                    divisors.append(m // d_prime)
        divisors.append(m) # m itself is always a divisor > 1

        N_C_m = 0
        for d_prime in divisors:
            # Since 3 does not divide m, 3 cannot divide d_prime, so C(d_prime) is well-defined.
            Nc_d_prime = C(d_prime)
            N_C_m += Nc_d_prime

        if N_C_m % 2 != 0:
            odd_m_list.append(m)

    return odd_m_list

