def count_odd_cycles(m):
    """
    Calculates the number of cycles whose length is odd for the permutation x -> 3x (mod m)
    on {1, ..., m-1}.
    """
    if m <= 1 or 3 % m == 0: # Constraint check: m must not be divisible by 3
        return -1 

    total_odd_cycles = 0

    # Iterate over all divisors g of m
    divisors = []
    for g in range(1, int(math.sqrt(m)) + 1):
        if m % g == 0:
            divisors.append(g)
            if g * g != m:
                divisors.append(m // g)

    for g in divisors:
        m_prime = m // g

        # The cycle length L is the order of 3 modulo m'
        L = order(3, m_prime)

        if L > 0 and L % 2 != 0:
            # The number of elements x such that gcd(x, m) = g is phi(m/g) = phi(m')
            # Wait, the elements are x = gy, where gcd(y, m')=1. There are phi(m') such y.
            num_elements = phi(m_prime)

            # The number of cycles of this length L is num_elements / L
            num_cycles = num_elements // L
            total_odd_cycles += num_cycles

    return total_odd_cycles

